if(new URLSearchParams(location.search).has('embedded'))document.body.classList.add('embedded');

const $=s=>document.querySelector(s), money=n=>new Intl.NumberFormat('es-EC',{style:'currency',currency:'USD'}).format(n);
const initial=[['Supermercado','Alimentación',-86.4,'2026-10-28'],['Sueldo','Ingresos',2850,'2026-10-27'],['Café y desayuno','Alimentación',-12.5,'2026-10-27'],['Internet','Servicios',-42,'2026-10-26'],['Combustible','Transporte',-35,'2026-10-26'],['Proyecto independiente','Ingresos',480,'2026-10-25'],['Restaurante','Ocio',-58,'2026-10-24'],['Electricidad','Servicios',-38.6,'2026-10-23'],['Libros','Ocio',-45,'2026-10-22'],['Transporte','Transporte',-14.5,'2026-10-21']];
let rows=initial.map(r=>[...r]),page='Resumen',days=30,extra=0,selected=12,query='',type='Todos',category='Todas',sort=false;
const payments=[['Tarjeta de crédito',482,'31 oct','Tarjeta principal'],['Vivienda',640,'03 nov','Cuenta principal'],['Servicios del hogar',68.4,'05 nov','Pago recurrente']];
const budgets={Alimentación:480,Transporte:180,Servicios:210,Ocio:250};
const names=['Resumen','Movimientos','Planificación','Análisis'];
const total=n=>rows.filter(r=>n==='income'?r[2]>0:r[2]<0).reduce((a,r)=>a+Math.abs(r[2]),0);
function notice(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#toast').style.display='none',2800)}
function openDialog(html){$('#dialog-content').innerHTML='<button class="close" data-action="close" aria-label="Cerrar diálogo">Cerrar</button>'+html;$('#dialog-content h2').id='dialog-title';$('#dialog').setAttribute('aria-labelledby','dialog-title');$('#dialog').showModal()}
function points(){return Array.from({length:13},(_,i)=>({day:Math.round(i*days/12),value:7860+Math.sin(i*1.25)*Math.sin(Math.PI*i/12)*280+(3320-1190.4)*(days/30)*(i/12)-extra*(i/12)}))}
function projection(){return points().at(-1).value}
function render(){
 $('#navigation').innerHTML=names.map(n=>`<button data-page="${n}" class="${page===n?'active':''}" aria-current="${page===n?'page':'false'}">${n}</button>`).join('');
 $('#breadcrumb').textContent='Finanzas / '+page;
 const titles={Resumen:['Tu dinero, en perspectiva','Disponible, próximos pagos y proyección en una sola lectura.'],Movimientos:['Movimientos','Busca, filtra y revisa tu actividad.'],Planificación:['Planifica con margen','Ajusta presupuestos y explora el efecto de tus decisiones.'],Análisis:['Entiende lo que cambia','Explora fechas, escenarios y distribución del gasto.']};
 $('#content').innerHTML=`<div class="page-head"><div><h1>${titles[page][0]}</h1><p>${titles[page][1]}</p></div><button class="primary" data-action="new">Nueva transacción</button></div>`+(page==='Movimientos'?transactionView():page==='Planificación'?planningView():overview(page==='Análisis'));
 if($('#chart'))drawChart(true);
 if($('#movement-rows')){drawRows();$('#search').value=query;}
}
function overview(analysis){return `${document.body.classList.contains('route')?sequence():''}<div class="grid"><section class="panel"><div class="section-head"><div><h2>Proyección de liquidez</h2><p class="helper">Saldo estimado tras los compromisos registrados</p></div><div class="periods" aria-label="Horizonte de proyección">${[30,60,90].map(d=>`<button data-days="${d}" class="${days===d?'active':''}" aria-pressed="${days===d}">${d} días</button>`).join('')}</div></div><div class="readout"><strong id="chart-value">${money(projection())}</strong><span id="chart-date">Al final de ${days} días</span></div><div class="legend"><span>Proyección ilustrativa</span><span>Saldo actual ${money(7860)}</span></div><svg id="chart" class="plot" viewBox="0 0 720 260" role="group" aria-label="Explora los puntos con Tab o el puntero"></svg><div class="annotation" id="annotation"></div><p class="helper">Recorre la curva con el puntero o enfoca un punto con Tab.</p>${analysis?scenario():''}<details><summary>Ver los datos de la gráfica</summary><div class="table-wrap"><table><thead><tr><th>Día</th><th>Saldo proyectado</th></tr></thead><tbody id="chart-data">${points().map(p=>`<tr><td>Día ${p.day}</td><td>${money(p.value)}</td></tr>`).join('')}</tbody></table></div></details></section><div class="stack"><section class="panel"><h2>Próximos pagos</h2>${paymentList()}</section><section class="panel"><h2>Disponible para gastar</h2><div class="readout"><strong id="available">${money(1420-extra)}</strong></div><p>Estimación a 30 días después de pagos y reserva.</p><button data-action="breakdown" style="margin-top:18px">Explorar desglose</button></section></div></div><div class="below"><section class="panel"><div class="section-head"><h2>${analysis?'Distribución del gasto':'Últimos movimientos'}</h2><button data-page="${analysis?'Análisis':'Movimientos'}" ${analysis?'data-action="categories"':''}>${analysis?'Cómo explorar':'Ver todos'}</button></div>${analysis?categories():miniRows()}</section><section class="panel"><h2>${analysis?'Lectura del periodo':'Gastos por categoría'}</h2>${analysis?'<p>La simulación muestra cómo un gasto adicional afecta la liquidez futura. Los pagos próximos se conservan dentro del escenario.</p><button data-action="sentinel" style="margin-top:22px">Abrir Centinela</button>':categories()}</section></div>`}
function sequence(){return `<div class="sequence"><div><small>Saldo actual</small><b>${money(7860)}</b></div><div><small>Ingresos previstos</small><b>+${money(3320*days/30)}</b></div><div><small>Pagos previstos</small><b>−${money(1190.4*days/30)}</b></div><div><small>Proyección a ${days} días</small><b>${money(projection())}</b></div></div>`}
function scenario(){return `<label class="scenario">Simular un gasto adicional: <strong id="extra-value">${money(extra)}</strong><input id="extra" type="range" min="0" max="3000" step="100" value="${extra}"><span class="helper">Escenario hipotético. No registra un movimiento.</span></label>`}
function drawChart(animate=false){const ps=points(),max=Math.max(10000,...ps.map(p=>p.value)),min=Math.min(5000,...ps.map(p=>p.value)),x=i=>50+i*54,y=v=>220-(v-min)/(max-min)*190;
 $('#chart').innerHTML=[0,1,2,3].map(i=>{const v=min+(max-min)*i/3;return `<path d="M50 ${y(v)}H700" stroke="var(--line)"/><text x="1" y="${y(v)-6}">${(v/1000).toFixed(1)}k</text>`}).join('')+`<path d="M50 ${y(7860)}H700" stroke="var(--muted)" stroke-dasharray="3 6" opacity=".6"/><path d="${ps.map((p,i)=>i?`C${x(i)-27} ${y(ps[i-1].value)} ${x(i)-27} ${y(p.value)} ${x(i)} ${y(p.value)}`:`M${x(i)} ${y(p.value)}`).join(' ')}" class="${animate?'series':''}" pathLength="1" fill="none" stroke="var(--accent)" stroke-width="3" stroke-linejoin="round"/><line id="cursor" x1="50" x2="50" y1="12" y2="220" stroke="var(--accent)" stroke-dasharray="3 4"/>`+ps.map((p,i)=>`<g class="point" data-point="${i}" tabindex="0" role="button" aria-label="Día ${p.day}: ${money(p.value)}"><rect x="${x(i)-22}" y="10" width="44" height="215" fill="transparent"/><circle cx="${x(i)}" cy="${y(p.value)}" r="3" fill="var(--panel)" stroke="var(--accent)" stroke-width="2"/></g>`).join('')+`<text x="50" y="250">Hoy</text><text x="330" y="250">Día ${Math.round(days/2)}</text><text x="645" y="250">Día ${days}</text>`;selectPoint(selected);if($('#chart-data'))$('#chart-data').innerHTML=ps.map(p=>`<tr><td>Día ${p.day}</td><td>${money(p.value)}</td></tr>`).join('');if($('#available'))$('#available').textContent=money(1420-extra);if($('.sequence'))$('.sequence').outerHTML=sequence()}
function selectPoint(i){selected=Number(i);const p=points()[selected];$('#chart-value').textContent=money(p.value);$('#chart-date').textContent=`Día ${p.day} · proyección`;$('#cursor').setAttribute('x1',50+selected*54);$('#cursor').setAttribute('x2',50+selected*54);$('#annotation').innerHTML=`<strong>${p.day===0?'Punto de partida':`Día ${p.day}`}</strong> · ${p.day===0?'Saldo registrado que inicia la simulación.':p.value>=7860?'El saldo estimado supera el saldo actual.':'Los compromisos reducen el saldo en este tramo.'}${extra?' Incluye el gasto hipotético de '+money(extra)+'.':''}`}
function paymentList(){return payments.map((p,i)=>`<button class="payment" data-payment="${i}"><span><strong>${p[0]}</strong><small>${p[2]} · ${p[3]}</small></span><b>${money(p[1])}</b></button>`).join('')}
function miniRows(){return rows.slice(0,4).map(r=>`<button class="payment" data-action="movements"><span><strong>${r[0]}</strong><small>${r[1]} · ${r[3]}</small></span><b class="${r[2]>0?'positive':'negative'}">${r[2]>0?'+':''}${money(r[2])}</b></button>`).join('')}
function categories(){const sums={};rows.filter(r=>r[2]<0).forEach(r=>sums[r[1]]=(sums[r[1]]||0)-r[2]);const max=Math.max(...Object.values(sums));return Object.entries(sums).sort((a,b)=>b[1]-a[1]).map(([c,v])=>`<button class="category" data-category="${c}"><span>${c}</span><b>${money(v)}</b><span class="bar"><i style="width:${v/max*100}%"></i></span></button>`).join('')}
function transactionView(){return `<section class="panel"><div class="summary-row"><div><small>Ingresos de la demo</small><b class="positive">${money(total('income'))}</b></div><div><small>Gastos de la demo</small><b>${money(total('expense'))}</b></div></div><div class="filters"><input id="search" type="search" placeholder="Buscar movimiento" aria-label="Buscar movimiento" ><select id="type" aria-label="Tipo">${['Todos','Ingresos','Gastos'].map(n=>`<option ${type===n?'selected':''}>${n}</option>`).join('')}</select><select id="category" aria-label="Categoría">${['Todas','Alimentación','Transporte','Servicios','Ocio','Ingresos'].map(n=>`<option ${category===n?'selected':''}>${n}</option>`).join('')}</select><button data-action="clear">Limpiar</button><button data-action="sort">Fecha ${sort?'ascendente':'descendente'}</button></div><p id="count" class="helper"></p><div class="table-wrap"><table><thead><tr><th>Descripción</th><th>Categoría</th><th>Fecha</th><th>Importe</th></tr></thead><tbody id="movement-rows"></tbody></table></div></section>`}
function drawRows(){const items=rows.filter(r=>r[0].toLocaleLowerCase().includes(query.toLocaleLowerCase())&&(type==='Todos'||(type==='Ingresos'?r[2]>0:r[2]<0))&&(category==='Todas'||r[1]===category)).sort((a,b)=>sort?a[3].localeCompare(b[3]):b[3].localeCompare(a[3]));$('#count').textContent=items.length+' movimientos';$('#movement-rows').innerHTML=items.length?items.map(r=>`<tr><td>${escapeText(r[0])}</td><td>${r[1]}</td><td>${r[3]}</td><td class="${r[2]>0?'positive':'negative'}">${r[2]>0?'+':''}${money(r[2])}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No hay coincidencias. Prueba otros filtros o pulsa Limpiar.</td></tr>'}
function planningView(){return `<div class="grid"><section class="panel"><h2>Presupuestos mensuales</h2><p>Ajusta los límites y observa el margen de cada categoría.</p>${Object.entries(budgets).map(([c,v])=>{const used=rows.filter(r=>r[1]===c&&r[2]<0).reduce((a,r)=>a-r[2],0);return `<div class="budget"><div class="section-head"><strong>${c}</strong><span>${money(used)} / <b id="limit-${c}">${money(v)}</b></span></div><input type="range" aria-label="Presupuesto de ${c}" data-budget="${c}" min="50" max="1000" step="10" value="${v}"><p id="remaining-${c}" class="helper">Margen: ${money(v-used)}</p></div>`}).join('')}</section><div class="stack"><section class="panel"><h2>Reserva de seguridad</h2><div class="readout"><strong>${money(1800)}</strong><span>de ${money(3000)}</span></div><div class="bar"><i style="width:60%"></i></div><p class="helper">60% de la meta de demostración</p><button data-action="goal" style="margin-top:20px">Simular aporte</button></section><section class="panel"><h2>Antes de decidir</h2><p>Explora cómo un gasto extraordinario modifica la proyección.</p><button data-page="Análisis" style="margin-top:20px">Simular escenario</button></section></div></div>`}
function escapeText(t){const el=document.createElement('span');el.textContent=t;return el.innerHTML}
document.addEventListener('click',e=>{const t=e.target.closest('button,[data-point]');if(!t)return;if(t.dataset.page){page=t.dataset.page;render()}if(t.dataset.days){days=Number(t.dataset.days);render()}if(t.dataset.category){category=t.dataset.category;page='Movimientos';render()}if(t.dataset.point)selectPoint(t.dataset.point);if(t.dataset.payment){const p=payments[Number(t.dataset.payment)];openDialog(`<h2>${p[0]}</h2><p>Detalle del compromiso de demostración.</p><div class="details-list"><div><span>Importe</span><b>${money(p[1])}</b></div><div><span>Vencimiento</span><b>${p[2]}</b></div><div><span>Origen</span><b>${p[3]}</b></div></div><p>Este prototipo muestra el detalle; no ejecuta pagos.</p>`)}
 const a=t.dataset.action;if(a==='close')$('#dialog').close();if(a==='theme')document.body.classList.toggle('alternate');if(a==='movements'){page='Movimientos';render()}if(a==='clear'){query='';category='Todas';type='Todos';render()}if(a==='sort'){sort=!sort;drawRows()}if(a==='categories')notice('Pulsa una categoría para ver sus movimientos filtrados.');if(a==='reset'){rows=initial.map(r=>[...r]);extra=0;days=30;Object.assign(budgets,{Alimentación:480,Transporte:180,Servicios:210,Ocio:250});query='';type='Todos';category='Todas';page='Resumen';render();notice('Demo restablecida')}
 if(a==='sentinel')openDialog('<h2>Centinela financiero</h2><p>Análisis ficticio ya preparado para explorar la interfaz.</p><div class="readout"><strong>84 / 100</strong></div><h3>Próximo compromiso</h3><p>Tu tarjeta vence el 31 de octubre. El saldo ilustrativo permite cubrirla.</p><h3>Acción sugerida</h3><p>Revisa los gastos de ocio antes de ampliar el presupuesto.</p><button data-action="review-analysis">Explorar análisis</button><p class="helper">No se consulta ningún servicio de IA.</p>');
 if(a==='review-analysis'){$('#dialog').close();page='Análisis';render()}if(a==='breakdown')openDialog('<h2>Desglose del disponible</h2><div class="details-list"><div><span>Saldo líquido</span><b>$ 7.860,00</b></div><div><span>Ingresos previstos</span><b>+$ 3.320,00</b></div><div><span>Pagos y compromisos</span><b>−$ 6.760,00</b></div><div><span>Reserva</span><b>−$ 3.000,00</b></div><div><span>Disponible proyectado</span><b>$ 1.420,00</b></div></div><p>Valores ficticios para revisar la presentación del desglose.</p>');
 if(a==='goal')openDialog('<h2>Simular aporte a tu reserva</h2><p>Reserva actual: $ 1.800,00 · Meta: $ 3.000,00</p><label class="scenario">Aporte <input id="goal-range" type="range" min="0" max="1200" step="50" value="200"><strong id="goal-output">Reserva resultante: $ 2.000,00 · 67%</strong></label>');
 if(a==='new')openDialog('<h2>Nueva transacción de demo</h2><p>Se añade a la lista ficticia durante esta visita.</p><form id="new-form"><label>Descripción<input name="description" required maxlength="80" placeholder="Ej. Compra de libros"></label><label>Importe en USD<input name="amount" type="number" min="0.01" step="0.01" max="100000" required></label><label>Tipo<select name="kind"><option>Gasto</option><option>Ingreso</option></select></label><label>Categoría<select name="category"><option>Alimentación</option><option>Ocio</option><option>Servicios</option><option>Transporte</option></select></label><button class="primary">Añadir a la demo</button></form>');
});
document.addEventListener('input',e=>{const t=e.target;if(t.id==='search'){query=t.value;drawRows()}if(t.id==='extra'){extra=Number(t.value);$('#extra-value').textContent=money(extra);drawChart()}if(t.dataset.budget){const c=t.dataset.budget;budgets[c]=Number(t.value);$('#limit-'+c).textContent=money(budgets[c]);const used=rows.filter(r=>r[1]===c&&r[2]<0).reduce((a,r)=>a-r[2],0);$('#remaining-'+c).textContent='Margen: '+money(budgets[c]-used)}if(t.id==='goal-range')$('#goal-output').textContent='Reserva resultante: '+money(1800+Number(t.value))+' · '+Math.round((1800+Number(t.value))/3000*100)+'%'});
document.addEventListener('change',e=>{if(e.target.id==='type'){type=e.target.value;drawRows()}if(e.target.id==='category'){category=e.target.value;drawRows()}});
document.addEventListener('pointerover',e=>{const p=e.target.closest('[data-point]');if(p)selectPoint(p.dataset.point)});document.addEventListener('focusin',e=>{const p=e.target.closest('[data-point]');if(p)selectPoint(p.dataset.point)});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-point]')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();selected=Math.max(0,Math.min(12,selected+(e.key==='ArrowRight'?1:-1)));document.querySelector(`[data-point="${selected}"]`).focus()}});
document.addEventListener('submit',e=>{if(e.target.id!=='new-form')return;e.preventDefault();const f=new FormData(e.target);const income=f.get('kind')==='Ingreso';rows.unshift([String(f.get('description')),income?'Ingresos':String(f.get('category')),Number(f.get('amount'))*(income?1:-1),'2026-10-28']);$('#dialog').close();page='Movimientos';query='';type='Todos';category='Todas';render();notice('Transacción añadida solo a la demo')});
render();
